const std = @import("std");
const math = std.math;

pub const KernelError = error{
    InvalidArgument,
    DivisionByZero,
    NullPointer,
    DimensionMismatch,
};

pub const BFloat16 = u16;

pub fn bfloat16ToFloat(val: BFloat16) f32 {
    const bits: u32 = @as(u32, val) << 16;
    return @bitCast(bits);
}

pub fn floatToBFloat16(val: f32) BFloat16 {
    const bits: u32 = @bitCast(val);
    return @truncate(bits >> 16);
}

fn sqrtf32(x: f32) f32 {
    return @sqrt(x);
}

fn expf32(x: f32) f32 {
    return @exp(x);
}

fn absf32(x: f32) f32 {
    return @abs(x);
}

fn tanhf32(x: f32) f32 {
    if (x > 20.0) return 1.0;
    if (x < -20.0) return -1.0;
    const ep = expf32(x);
    const em = expf32(-x);
    return (ep - em) / (ep + em);
}

fn erff32(x: f32) f32 {
    const a1: f32 = 0.254829592;
    const a2: f32 = -0.284496736;
    const a3: f32 = 1.421413741;
    const a4: f32 = -1.453152027;
    const a5: f32 = 1.061405429;
    const p: f32 = 0.3275911;
    const sign: f32 = if (x < 0.0) -1.0 else 1.0;
    const ax = absf32(x);
    const t = 1.0 / (1.0 + p * ax);
    const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * expf32(-ax * ax);
    return sign * y;
}

pub fn sumOfSquares(data: []const f32, len: usize) f32 {
    var s: f32 = 0.0;
    var i: usize = 0;
    while (i < len) : (i += 1) {
        s += data[i] * data[i];
    }
    return s;
}

pub fn rmsnormForwardRow(
    row_in: []const f32,
    weight: []const f32,
    row_out: []f32,
    normalized_shape: usize,
    eps: f32,
) void {
    const ns_f: f32 = @floatFromInt(normalized_shape);
    var sum_sq: f32 = 0.0;
    var i: usize = 0;
    while (i < normalized_shape) : (i += 1) {
        sum_sq += row_in[i] * row_in[i];
    }
    const mean_sq = sum_sq / ns_f;
    const rsqrt_val = 1.0 / sqrtf32(mean_sq + eps);
    i = 0;
    while (i < normalized_shape) : (i += 1) {
        row_out[i] = row_in[i] * rsqrt_val * weight[i];
    }
}

pub fn rmsnormForward(
    input: []const BFloat16,
    weight: []const BFloat16,
    output: []BFloat16,
    n_rows: usize,
    normalized_shape: usize,
    eps: f32,
) KernelError!void {
    if (normalized_shape == 0) return KernelError.DivisionByZero;
    if (n_rows == 0) return;
    if (input.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (output.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (weight.len < normalized_shape) return KernelError.InvalidArgument;

    const ns_f: f32 = @floatFromInt(normalized_shape);
    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        var sum_sq: f32 = 0.0;
        var i: usize = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            sum_sq += val * val;
        }
        const mean_sq = sum_sq / ns_f;
        const rsqrt_val = 1.0 / sqrtf32(mean_sq + eps);
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            const w = bfloat16ToFloat(weight[i]);
            output[row_start + i] = floatToBFloat16(val * rsqrt_val * w);
        }
    }
}

pub fn rmsnormBackward(
    grad_output: []const BFloat16,
    input: []const BFloat16,
    weight: []const BFloat16,
    grad_input: []BFloat16,
    grad_weight: ?[]f32,
    n_rows: usize,
    normalized_shape: usize,
    eps: f32,
) KernelError!void {
    if (normalized_shape == 0) return KernelError.DivisionByZero;
    if (n_rows == 0) return;
    if (grad_output.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (input.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (grad_input.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (weight.len < normalized_shape) return KernelError.InvalidArgument;
    if (grad_weight) |gw| {
        if (gw.len < normalized_shape) return KernelError.InvalidArgument;
    }

    const ns_f: f32 = @floatFromInt(normalized_shape);
    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        var sum_sq: f32 = 0.0;
        var i: usize = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            sum_sq += val * val;
        }
        const mean_sq = sum_sq / ns_f;
        const rsqrt_val = 1.0 / sqrtf32(mean_sq + eps);
        var sum_grad_weighted: f32 = 0.0;
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const g = bfloat16ToFloat(grad_output[row_start + i]);
            const w = bfloat16ToFloat(weight[i]);
            const x = bfloat16ToFloat(input[row_start + i]);
            sum_grad_weighted += g * w * x;
        }
        const rsqrt_cubed = rsqrt_val * rsqrt_val * rsqrt_val;
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const g = bfloat16ToFloat(grad_output[row_start + i]);
            const w = bfloat16ToFloat(weight[i]);
            const x = bfloat16ToFloat(input[row_start + i]);
            const grad_val = w * rsqrt_val * g - x * sum_grad_weighted * rsqrt_cubed / ns_f;
            grad_input[row_start + i] = floatToBFloat16(grad_val);
            if (grad_weight) |gw| {
                gw[i] += g * x * rsqrt_val;
            }
        }
    }
}

pub fn layernormForward(
    input: []const BFloat16,
    weight: []const BFloat16,
    bias: ?[]const BFloat16,
    output: []BFloat16,
    n_rows: usize,
    normalized_shape: usize,
    eps: f32,
) KernelError!void {
    if (normalized_shape == 0) return KernelError.DivisionByZero;
    if (n_rows == 0) return;
    if (input.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (output.len < n_rows * normalized_shape) return KernelError.InvalidArgument;
    if (weight.len < normalized_shape) return KernelError.InvalidArgument;
    if (bias) |b| {
        if (b.len < normalized_shape) return KernelError.InvalidArgument;
    }

    const ns_f: f32 = @floatFromInt(normalized_shape);
    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        var mean: f32 = 0.0;
        var i: usize = 0;
        while (i < normalized_shape) : (i += 1) {
            mean += bfloat16ToFloat(input[row_start + i]);
        }
        mean = mean / ns_f;
        var variance: f32 = 0.0;
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            const diff = val - mean;
            variance += diff * diff;
        }
        variance = variance / ns_f;
        const inv_std = 1.0 / sqrtf32(variance + eps);
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            const w = bfloat16ToFloat(weight[i]);
            const b_val: f32 = if (bias) |b| bfloat16ToFloat(b[i]) else 0.0;
            const normalized = (val - mean) * inv_std;
            output[row_start + i] = floatToBFloat16(normalized * w + b_val);
        }
    }
}

pub fn geluApproximate(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const x3 = x * x * x;
    const tanh_arg = sqrt_2_over_pi * (x + 0.044715 * x3);
    return 0.5 * x * (1.0 + tanhf32(tanh_arg));
}

pub fn geluExact(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const erf_val = erff32(x / sqrt2);
    return 0.5 * x * (1.0 + erf_val);
}

pub fn geluForward(
    input: []const BFloat16,
    output: []BFloat16,
    numel: usize,
    approximate: bool,
) KernelError!void {
    if (input.len < numel) return KernelError.InvalidArgument;
    if (output.len < numel) return KernelError.InvalidArgument;
    var i: usize = 0;
    while (i < numel) : (i += 1) {
        const x = bfloat16ToFloat(input[i]);
        const y = if (approximate) geluApproximate(x) else geluExact(x);
        output[i] = floatToBFloat16(y);
    }
}

pub fn geluApproxBackward(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const x3 = x * x * x;
    const tanh_arg = sqrt_2_over_pi * (x + 0.044715 * x3);
    const tanh_val = tanhf32(tanh_arg);
    const sech_sq = 1.0 - tanh_val * tanh_val;
    const inner_deriv = sqrt_2_over_pi * (1.0 + 3.0 * 0.044715 * x * x);
    return 0.5 * (1.0 + tanh_val) + 0.5 * x * sech_sq * inner_deriv;
}

pub fn geluExactBackward(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const cdf = 0.5 * (1.0 + erff32(x / sqrt2));
    const pdf = expf32(-0.5 * x * x) * 0.3989422804014327;
    return cdf + x * pdf;
}

pub fn geluBackward(
    grad_output: []const BFloat16,
    input: []const BFloat16,
    grad_input: []BFloat16,
    numel: usize,
    approximate: bool,
) KernelError!void {
    if (grad_output.len < numel) return KernelError.InvalidArgument;
    if (input.len < numel) return KernelError.InvalidArgument;
    if (grad_input.len < numel) return KernelError.InvalidArgument;
    var i: usize = 0;
    while (i < numel) : (i += 1) {
        const x = bfloat16ToFloat(input[i]);
        const g = bfloat16ToFloat(grad_output[i]);
        const grad_val = if (approximate) geluApproxBackward(x) else geluExactBackward(x);
        grad_input[i] = floatToBFloat16(g * grad_val);
    }
}

pub fn softmaxForward(
    input: []const BFloat16,
    output: []BFloat16,
    outer_size: usize,
    dim_size: usize,
    inner_size: usize,
) KernelError!void {
    if (dim_size == 0) return KernelError.DivisionByZero;
    if (inner_size == 0) return KernelError.InvalidArgument;
    if (outer_size == 0) return;
    const total = outer_size * dim_size * inner_size;
    if (input.len < total) return KernelError.InvalidArgument;
    if (output.len < total) return KernelError.InvalidArgument;

    var outer: usize = 0;
    while (outer < outer_size) : (outer += 1) {
        var inner: usize = 0;
        while (inner < inner_size) : (inner += 1) {
            const base = outer * dim_size * inner_size + inner;
            var max_val: f32 = -math.inf(f32);
            var d: usize = 0;
            while (d < dim_size) : (d += 1) {
                const val = bfloat16ToFloat(input[base + d * inner_size]);
                if (val > max_val) {
                    max_val = val;
                }
            }
            var sum_exp: f32 = 0.0;
            d = 0;
            while (d < dim_size) : (d += 1) {
                const val = bfloat16ToFloat(input[base + d * inner_size]);
                const exp_val = expf32(val - max_val);
                sum_exp += exp_val;
                output[base + d * inner_size] = floatToBFloat16(exp_val);
            }
            if (sum_exp == 0.0) {
                const uniform: f32 = 1.0 / @as(f32, @floatFromInt(dim_size));
                d = 0;
                while (d < dim_size) : (d += 1) {
                    output[base + d * inner_size] = floatToBFloat16(uniform);
                }
            } else {
                d = 0;
                while (d < dim_size) : (d += 1) {
                    const val = bfloat16ToFloat(output[base + d * inner_size]);
                    output[base + d * inner_size] = floatToBFloat16(val / sum_exp);
                }
            }
        }
    }
}

pub fn validateNormArgs(numel: usize, normalized_shape: usize) KernelError!struct { n_rows: usize, block_size: usize } {
    if (normalized_shape == 0) return KernelError.DivisionByZero;
    if (numel % normalized_shape != 0) return KernelError.DimensionMismatch;
    const n_rows = numel / normalized_shape;
    if (n_rows == 0) return KernelError.InvalidArgument;
    const block_size = if (normalized_shape < 256) normalized_shape else 256;
    if (block_size == 0) return KernelError.InvalidArgument;
    return .{ .n_rows = n_rows, .block_size = block_size };
}
