  ∀ (x : F32), geluExactSpec x =
    F32.mul (F32.mul (F32.mk' 0.5) x)
      (F32.add (F32.mk' 1.0)
        (erffApprox (F32.div x (F32.mk' 1.4142135623730951)))) :=
  fun _ => Eq.refl _

theorem geluApproxBackward_spec_def :
  ∀ (x : F32), geluApproxBackwardSpec x =
    F32.add
      (F32.mul (F32.mk' 0.5)
        (F32.add (F32.mk' 1.0)
          (tanhApproxF32
            (F32.mul (F32.mk' 0.7978845608028654)
              (F32.add x (F32.mul (F32.mk' 0.044715) (F32.mul x (F32.mul x x))))))))
      (F32.mul (F32.mul (F32.mk' 0.5) x)
        (F32.mul
          (F32.sub (F32.mk' 1.0)
            (F32.mul
              (tanhApproxF32
                (F32.mul (F32.mk' 0.7978845608028654)
                  (F32.add x (F32.mul (F32.mk' 0.044715) (F32.mul x (F32.mul x x))))))
              (tanhApproxF32
                (F32.mul (F32.mk' 0.7978845608028654)
                  (F32.add x (F32.mul (F32.mk' 0.044715) (F32.mul x (F32.mul x x))))))))
          (F32.mul (F32.mk' 0.7978845608028654)
            (F32.add (F32.mk' 1.0) (F32.mul (F32.mul (F32.mk' 3.0) (F32.mk' 0.044715)) (F32.mul x x)))))) :=
  fun _ => Eq.refl _

theorem geluExactBackward_spec_def :
  ∀ (x : F32), geluExactBackwardSpec x =
    F32.add
      (F32.mul (F32.mk' 0.5)
        (F32.add (F32.mk' 1.0)
          (erffApprox (F32.div x (F32.mk' 1.4142135623730951)))))
      (F32.mul x
        (F32.mul (F32.exp (F32.neg (F32.mul (F32.mul (F32.mk' 0.5) x) x))) (F32.mk' 0.3989422804014327))) :=
