theorem softmaxNormalize_length :
  ∀ (xs : List F32) (m s : F32), (softmaxNormalize xs m s).length = xs.length :=
  fun xs m s =>
    match xs with
    | [] => Eq.refl _
    | _ :: rest =>
      congrArg Nat.succ (softmaxNormalize_length rest m s)

theorem softmaxRow_length :
  ∀ (xs : List F32), (softmaxRowSpec xs).length = xs.length :=
  fun xs =>
    match xs with
    | [] => Eq.refl _
    | x :: rest => softmaxNormalize_length (x :: rest) (softmaxFindMax (x :: rest)) (softmaxSumExp (x :: rest) (softmaxFindMax (x :: rest)))
